e{font-family:var(--mono);letter-spacing:.22em;font-size:var(--fs-code)}.account{padding:var(--s-5);border-radius:var(--r-md);background:var(--soft);display:grid;gap:var(--s-5)}.account dl{margin:0;display:grid;gap:var(--s-4)}.account dt{font-size:var(--fs-body);color:var(--muted)}.account dd{margin:var(--s-1) 0 0;font-family:var(--mono);font-size:var(--fs-lg)}.account .balance{font-size:var(--fs-3xl);font-family:var(--plex)}dialog{color:var(--fg);background:var(--surface);border:var(--border) solid var(--line);border-radius:var(--r-lg);padding:var(--s-6);width:calc(100% - var(--s-7));max-width:var(--bank-width);box-shadow:var(--shadow)}dialog::backdrop{background:#00000066}dialog h2{margin-bottom:var(--s-4)}dialog p{margin-bottom:var(--s-5)}dialog .phone{display:flex;align-items:center;justify-content:center;border:var(--border) solid var(--accent);border-radius:var(--r-md);text-decoration:none;font-weight:600;padding:var(--s-3);margin-bottom:var(--s-5)}dialog .hint{margin-bottom:var(--s-5)}dialog button{width:100%}
@media(max-width:1100px){.dashboard-layout{grid-template-columns:1fr}.sidebar{grid-template-columns:repeat(3,1fr)}.incident-head,.incident{grid-template-columns:90px minmax(200px,1fr) 120px 100px 130px}.dashboard #app{padding:var(--s-5)}}
@media(max-width:360px){.bank #app{padding:var(--s-5);gap:var(--s-6)}.bank h1{font-size:var(--fs-2xl)}.bank-content{gap:var(--s-5)}.bank form{gap:var(--s-5)}.bank .brand{font-size:var(--fs-xl)}}
@media(prefers-reduced-motion:reduce){*{transition:none"'!important;scroll-behavior:auto!important}}
EOF'

