function bank(){const b=F.bank;document.title="'`${b.name} · Account setup`;let content='"'',bottom='';
if(state==='welcome') {content="'`<section><p class="step">Your everyday banking</p><h1>A simple start.<br>A fresh account.</h1><p class="intro">Let’s set up your ${b.accountName.toLowerCase()}.</p></section><ul class="benefits"><li><span class="tick" aria-hidden="true">✓</span><span>Enter your name and mobile number</span></li><li><span class="tick" aria-hidden="true">✓</span><span>Confirm it’s you with a text message</span></li><li><span class="tick" aria-hidden="true">✓</span><span>See your new account details</span></li></ul>${button('"'Get started','details','primary wide')}"'`;bottom='"'You’ll need a mobile phone that can receive text messages.';}
if(state==='details'||state==='details-error'){if(state==='details-error'&&"'!nameError&&!mobileError){nameError='"'Enter your full name, as it appears on your ID.';mobileError='Enter a UK mobile number, for example starting with 07.';}
content="'`<section><p class="step">Step 1 of 2</p><h1>First, your details</h1><p class="intro">We’ll send a text message to confirm your mobile number.</p></section><form id="details-form" novalidate><div class="form-field"><label for="full-name">Full name</label><input id="full-name" name="name" autocomplete="name" value="${esc(customer)}" aria-describedby="name-hint${nameError?'"' name-error':''}\" "'${nameError?'"'aria-invalid=\"true\"':''}><p id=\"name-hint\" class=\"hint\">As it appears on your ID</p>"'${nameError?`<p id="name-error" class="field-error">${nameError}</p>`:'"''}</div><div class=\"form-field\"><label for=\"mobile\">Mobile number</label><input id=\"mobile\" name=\"mobile\" type=\"tel\" inputmode=\"tel\" autocomplete=\"tel\" value=\""'${esc(mobile)}" aria-describedby="mobile-hint${mobileError?'"' mobile-error':''}\" "'${mobileError?'"'aria-invalid=\"true\"':''}><p id=\"mobile-hint\" class=\"hint\">A UK number starting with 07 or +44</p>"'${mobileError?`<p id="mobile-error" class="field-error">${mobileError}</p>`:'"''}</div><button class=\"primary wide\" type=\"submit\">Send me a code</button></form>"'${back('"'welcome')}"'`;bottom='"'Your details are used to set up this account.';}
