app.innerHTML=`${bankHeader()}<div class="bank-content">${content}</div>${bottom?`<footer class="bank-footer">${bottom}</footer>`:'"''}<dialog id=\"help-dialog\" aria-labelledby=\"help-title\" aria-describedby=\"help-description\"><h2 id=\"help-title\">We’re here to help</h2><p id=\"help-description\">Having trouble setting up your account? Speak to a person on our support team.</p><a class=\"phone\" href=\"tel:"'${b.helpPhone.replace(/ /g,'"'')}\">Call "'${b.helpPhone}</a><p class="hint">${b.warning}</p><button class="primary" id="close-help">Back to setup</button></dialog>`;
