if(action==='accepted-schedule'){acceptedSchedule=true;pendingSchedule=false;go('main');return;}
if(action==='finish'){control.textContent='Setup complete';control.disabled=true;return;}
if(action==='main'){review=false;}go(action);
});
window.addEventListener('message',e=>{if(e.data==='simulate-acceptance'&&family==='menu'&&(state==='pending'||pendingSchedule)){pendingSchedule=false;acceptedSchedule=true;go('accepted');}});
render();
})();
EOF
